package com.aionui.notifier.data

import org.json.JSONObject

/** A pairing id is a one-use, high-entropy capability generated by the desktop. */
data class PairingCode(val projectId: String, val pairingId: String, val expiresAt: Long) {
    companion object {
        fun parse(raw: String, now: Long = System.currentTimeMillis()): PairingCode? =
            runCatching {
                    if (raw.length > 2048) return null
                    val json = JSONObject(raw)
                    if (json.optInt("v") != 1 || json.optString("type") != "aionui_pairing")
                        return null
                    val project = json.getString("projectId")
                    val id = json.getString("pairingId")
                    val expires = json.getLong("expiresAt")
                    if (!Regex("[a-z][a-z0-9-]{4,62}").matches(project)) return null
                    if (!Regex("[A-Za-z0-9_-]{43,128}").matches(id)) return null
                    if (expires <= now || expires > now + 600_000) return null
                    PairingCode(project, id, expires)
                }
                .getOrNull()
    }
}
